let equipmentDocumentRequest=0;
function resetEquipmentDocuments(){updateDocumentEquipment();equipmentDocumentRequest++;$('equipment-document-list').replaceChildren();$('equipment-document-count').textContent='';$('equipment-document-context').textContent='Select equipment to attach its PDFs.';}
async function loadEquipmentDocuments(){updateDocumentEquipment();const ship=$('draft-ship_id').value,equipment=$('equipment-selector').value;if(!ship||!equipment||equipment==='__legacy'){resetEquipmentDocuments();return;}const request=++equipmentDocumentRequest;const item=equipmentItems.find(x=>x.equipment_id===equipment);$('equipment-document-context').textContent=($('draft-ship_name').value||ship)+' · '+(item?.name||equipment);try{const docs=await api('equipment-documents?ship_id='+encodeURIComponent(ship)+'&equipment_id='+encodeURIComponent(equipment));if(request!==equipmentDocumentRequest)return;$('equipment-document-count').textContent=' · '+docs.length+' documents';$('equipment-document-list').innerHTML=docs.map(d=>`<article class="panel"><a href="${'/api/equipment-documents/'+encodeURIComponent(d.id)+'/file'}">${esc(d.name)}</a><p>Revision: ${esc(d.revision)} · ${d.page_count} pages · ${esc(d.pages_without_text.length?'Text + visual pages available':'Text indexed · visual pages available')}</p><small>${esc(d.scope==='class'?'Class + equipment model':'This ship + equipment')} · ${d.indexed_pages} pages searchable</small>${d.pages_without_text.length?`<p>${d.pages_without_text.length} page(s) have no extractable text. Open the page viewer to distinguish graphics, scans and likely blank pages.</p>`:''}<details class="pdf-viewer" data-document="${esc(d.id)}"><summary>View diagrams &amp; pages</summary><div class="pdf-viewer-body"></div></details></article>`).join('')||'<p>No PDFs linked to this equipment yet. Upload a schematic or manual above.</p>'}catch(e){$('equipment-document-status').textContent='Unable to load documents: '+e.message}}
$('equipment-document-upload').onsubmit=async e=>{e.preventDefault();const ship=$('draft-ship_id').value,equipment=$('equipment-document-equipment').value;if(!ship||!equipment){$('equipment-document-status').textContent='Select a ship and equipment first.';return;}const button=e.submitter;button.disabled=true;let saved=0;const revision=$('equipment-document-revision').value.trim()||'Not specified',scope=$('equipment-document-scope').value,files=[...$('equipment-document-files').files];try{await flushDraft();for(const file of files){if(file.size>20*1024*1024)throw Error(file.name+' exceeds 20 MB');$('equipment-document-status').textContent='Uploading and extracting text: '+file.name;const response=await fetch('/api/equipment-documents?'+new URLSearchParams({ship_id:ship,equipment_id:equipment,scope,revision}),{method:'POST',headers:{'X-Filename':encodeURIComponent(file.name)},body:file});const d=await response.json();if(!response.ok)throw Error(typeof d.detail==='string'?d.detail:JSON.stringify(d.detail));saved++;}$('equipment-document-files').value='';$('equipment-document-status').textContent=saved+' PDF(s) saved and queued for synchronization with the selected scope. Check indexing status below.';}catch(err){$('equipment-document-status').textContent=saved+' saved. '+err.message}finally{button.disabled=false;await loadEquipmentDocuments();await loadCatalog()}};

