$('watch-search').addEventListener('focus',()=>{$('work-order-menu').open=true});
$('watch-search').addEventListener('keydown',e=>{if(e.key==='ArrowDown'){e.preventDefault();$('work-order-menu').open=true;$('jobs').querySelector('button')?.focus()}if(e.key==='Escape'){$('work-order-menu').open=false}});
$('jobs').addEventListener('keydown',e=>{const rows=[...$('jobs').querySelectorAll('[data-open-job]')],index=rows.indexOf(e.target);if(index<0)return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();rows[Math.max(0,Math.min(rows.length-1,index+(e.key==='ArrowDown'?1:-1)))].focus()}if(e.key==='Escape'){e.preventDefault();$('watch-search').focus();$('work-order-menu').open=false}});
